/**
 * Image Storage settings page - S3-compatible object storage for avatars
 */
import { useEffect, useMemo } from 'react';
import { LoadingSpinner } from '../../shared/LoadingSpinner';
import { ErrorMessage } from '../../shared/ErrorMessage';
import { useSettingsAutosave } from '../../../hooks/useSettingsAutosave';
import { SettingsSection } from './settingsInputs';
import { AutosaveStatus } from './AutosaveStatus';

const IMAGE_STORAGE_FIELDS = [
  'image_storage_enabled',
  'image_storage_provider',
  'image_storage_bucket',
  'image_storage_region',
  'image_storage_endpoint',
  'image_storage_access_key',
  'image_storage_secret_key',
  'image_storage_cdn_url',
];

/** DigitalOcean endpoint hint by region */
const DO_ENDPOINT_HINT: Record<string, string> = {
  nyc3: 'https://nyc3.digitaloceanspaces.com',
  ams3: 'https://ams3.digitaloceanspaces.com',
  sgp1: 'https://sgp1.digitaloceanspaces.com',
  sfo3: 'https://sfo3.digitaloceanspaces.com',
  fra1: 'https://fra1.digitaloceanspaces.com',
  syd1: 'https://syd1.digitaloceanspaces.com',
};

export interface ImageStorageSettingsProps {
  className?: string;
}

export function ImageStorageSettings({ className }: ImageStorageSettingsProps) {
  const {
    settings,
    edits,
    isLoading,
    autosaveStatus,
    autosaveError,
    error,
    fetchSettings,
    handleChange,
    getEffectiveValue,
  } = useSettingsAutosave();

  useEffect(() => {
    fetchSettings();
  }, [fetchSettings]);

  const currentSettings = useMemo(() => {
    const categorySettings = settings['image_storage'] ?? [];
    return categorySettings
      .filter((s) => IMAGE_STORAGE_FIELDS.includes(s.key))
      .sort((a, b) => IMAGE_STORAGE_FIELDS.indexOf(a.key) - IMAGE_STORAGE_FIELDS.indexOf(b.key));
  }, [settings]);

  // Provider-aware change handler
  const handleProviderAwareChange = (key: string, value: string) => {
    handleChange(key, value);

    if (key === 'image_storage_provider') {
      if (value === 'digitalocean') {
        // Hint: fill region and endpoint for DO Spaces
        const region = getEffectiveValue('image_storage_region') || 'nyc3';
        handleChange('image_storage_region', region);
        handleChange('image_storage_endpoint', DO_ENDPOINT_HINT[region] ?? `https://${region}.digitaloceanspaces.com`);
      } else if (value === 's3') {
        // AWS S3: clear endpoint (uses default)
        handleChange('image_storage_endpoint', '');
      }
    }

    // Auto-update DO endpoint when region changes
    if (key === 'image_storage_region' && getEffectiveValue('image_storage_provider') === 'digitalocean') {
      handleChange('image_storage_endpoint', DO_ENDPOINT_HINT[value] ?? `https://${value}.digitaloceanspaces.com`);
    }
  };

  if (isLoading && Object.keys(settings).length === 0) {
    return (
      <div className={`cedros-system-settings cedros-system-settings-loading ${className ?? ''}`}>
        <LoadingSpinner />
        <span>Loading settings...</span>
      </div>
    );
  }

  if (error) {
    return (
      <div className={`cedros-system-settings ${className ?? ''}`}>
        <ErrorMessage error={error.message} />
      </div>
    );
  }

  return (
    <div className={`cedros-system-settings ${className ?? ''}`}>
      <div className="cedros-settings-page-header">
        <div className="cedros-settings-page-header-content">
          <h2 className="cedros-settings-page-title">Image Storage</h2>
          <p className="cedros-settings-page-description">
            Configure S3-compatible object storage for user avatars and images. Supports AWS S3,
            DigitalOcean Spaces, and other S3-compatible providers.
          </p>
        </div>
        <AutosaveStatus status={autosaveStatus} error={autosaveError} />
      </div>

      {currentSettings.length === 0 ? (
        <div className="cedros-system-settings-empty">
          <p>No image storage settings found.</p>
        </div>
      ) : (
        <SettingsSection
          settings={currentSettings}
          edits={edits}
          onChange={handleProviderAwareChange}
        />
      )}
    </div>
  );
}
